solution.javascript:
function solveNQueens(n) {
  const result = [];
  const cols = new Set(), diag1 = new Set(), diag2 = new Set();
  const board = Array(n).fill(null).map(() => Array(n).fill('.'));
  function backtrack(row) {
    if (row === n) { result.push(board.map(r => r.join(''))); return; }
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || diag1.has(row-c) || diag2.has(row+c)) continue;
      cols.add(c); diag1.add(row-c); diag2.add(row+c);
      board[row][c] = 'Q';
      backtrack(row + 1);
      board[row][c] = '.';
      cols.delete(c); diag1.delete(row-c); diag2.delete(row+c);
    }
  }
  backtrack(0);
  return result;
}

solution.cpp:
vector<vector<string>> solveNQueens(int n) {
    vector<vector<string>> result;
    vector<string> board(n, string(n, '.'));
    unordered_set<int> cols, diag1, diag2;
    function<void(int)> bt = [&](int row) {
        if (row == n) { result.push_back(board); return; }
        for (int c = 0; c < n; c++) {
            if (cols.count(c) || diag1.count(row-c) || diag2.count(row+c)) continue;
            cols.insert(c); diag1.insert(row-c); diag2.insert(row+c);
            board[row][c] = 'Q';
            bt(row + 1);
            board[row][c] = '.';
            cols.erase(c); diag1.erase(row-c); diag2.erase(row+c);
        }
    };
    bt(0);
    return result;
}
